import json

# Load the existing transform function
def transform(grid):
    """Apply transformation rule."""
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        row_orig = grid[r]
        leading_3s = 0
        for c in range(len(row_orig)):
            if row_orig[c] == 3:
                leading_3s += 1
            else:
                break
        if leading_3s > 2:
            result[r] = [1 if x == 2 else x for x in row_orig]
    return result

# Load demo grids
with open("task-000641e2.json") as f:
    data = json.load(f)
input_grid = data["demos"][0]
output_grid = data["demos"][1]

# Verify
computed = transform(input_grid)
verifies = all(computed[r] == output_grid[r] for r in range(len(output_grid)))
print(f"Transform verifies: {verifies}")

# Check rule: rows have more than 2 leading 3s, and change 2s to 1s
# Let's look at the transition
for r in range(len(input_grid)):
    inp = input_grid[r]
    out = output_grid[r]
    if out != inp:
        print(f"\nRow {r} changed:")
        for c in range(len(inp)):
            if inp[c] != out[c]:
                print(f"  [{c}]: {inp[c]} -> {out[c]}")

# Check leading 3s count
print("\nLeading 3s per row in input:")
for r in range(len(input_grid)):
    leading = 0
    for c in range(len(input_grid[r])):
        if input_grid[r][c] == 3:
            leading += 1
        else:
            break
    has_change = input_grid[r] != output_grid[r]
    print(f"  Row {r}: {leading} leading 3s, changed: {has_change}")

